INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-belgium-mandatory-b2b-peppol', 'es', 'Bélgica — facturación electrónica B2B obligatoria vía Peppol', 'El mandato de facturación electrónica B2B de Bélgica entra en vigor, exigiendo Peppol BIS 3.0 para todas las transacciones nacionales entre sujetos pasivos de IVA.', '<h3>🇧🇪 Bélgica — facturación electrónica B2B obligatoria vía Peppol</h3><p>La facturación electrónica estructurada es ahora obligatoria para las transacciones B2B nacionales entre empresas belgas registradas a efectos de IVA, usando Peppol BIS Billing 3.0 / EN 16931. Las facturas en PDF y papel ya no son válidas a partir de hoy. Un período de tolerancia administrativa de tres meses se extiende hasta el 1 de abril, tras el cual se aplica un régimen de sanciones progresivas (1.500 € / 3.000 € / 5.000 € por infracción) — así que esta ventana merece realmente usarse para cerrar cualquier brecha pendiente, no solo para esperar a que pase.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium" target="_blank" rel="noopener">🔗 Fuente oficial: EU Digital Building Blocks — Bélgica</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-brazil-cbs-ibs-test-fields', 'es', 'Brasil — se requieren campos de prueba CBS/IBS', 'Comienza la reforma del IVA dual de Brasil, exigiendo nuevos campos de prueba CBS/IBS en los documentos NF-e, NFC-e y NFS-e.', '<h3>🇧🇷 Brasil — se requieren campos de prueba CBS/IBS</h3><p>A medida que comienza la reforma del IVA dual de Brasil, los documentos fiscales electrónicos (NF-e, NFC-e, NFS-e) deben incluir ahora los nuevos campos CBS e IBS con tasas de prueba del 0,9% y 0,1% respectivamente. Aún no hay impacto financiero con estas tasas de prueba, pero la obligación legal de incluir los datos correctamente ya se aplica — y la validación se endurece considerablemente a partir de abril.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.nfe.fazenda.gov.br/portal/principal.aspx" target="_blank" rel="noopener">🔗 Fuente oficial: Portal Nacional da NF-e (SEFAZ)</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-croatia-fiskalizacija-2', 'es', 'Croacia — entra en vigor Fiskalizacija 2.0', 'Fiskalizacija 2.0 de Croacia exige facturación electrónica B2B estructurada y reporte electrónico en tiempo real para todos los sujetos pasivos de IVA.', '<h3>🇭🇷 Croacia — entra en vigor Fiskalizacija 2.0</h3><p>La mayor reforma de facturación electrónica de Croacia hasta la fecha: la emisión estructurada, la recepción y el reporte electrónico en tiempo real son ahora obligatorios para todos los contribuyentes registrados a efectos de IVA y establecidos en Croacia — superpuesto al mandato B2G ya vigente desde 2019. Esto incluye un flujo de fiscalización de 5 días por parte del comprador y un reporte electrónico mensual antes del día 20 de cada mes, además de un requisito de archivo de 11 años para las facturas XML originales.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://porezna-uprava.gov.hr/en" target="_blank" rel="noopener">🔗 Fuente oficial: Porezna uprava (Administración Tributaria de Croacia)</a></p><p><strong>Qué significa esto para su equipo:</strong> si opera en cualquiera de estos seis mercados, este es el momento de confirmar — no asumir — que lo que se puso en marcha durante las fiestas funciona realmente correctamente en producción, no solo que está configurado y sin probar.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-malaysia-myinvois-phase-4', 'es', 'Malasia — comienza la Fase 4 de MyInvois', 'La Fase 4 de MyInvois incorpora al mandato de facturación electrónica de Malasia a las empresas con una facturación de entre RM1 y 5 millones.', '<h3>🇲🇾 Malasia — comienza la Fase 4 de MyInvois</h3><p>Las empresas con una facturación anual de entre RM1 millón y RM5 millones entran hoy en el mandato, con un período de flexibilización en las sanciones por errores de presentación que se extiende hasta finales de 2027. Las facturas electrónicas individuales por encima de RM10.000 son ahora obligatorias — la facturación consolidada ya no está permitida para importes de ese nivel.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Fuente oficial: LHDN — MyInvois / e-Invoice</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-mexico-2026-tax-reform', 'es', 'México — entra en vigor la reforma fiscal 2026', 'La reforma fiscal 2026 de México refuerza las facultades de fiscalización del SAT, introduciendo responsabilidad penal por CFDI falsos.', '<h3>🇲🇽 México — entra en vigor la reforma fiscal 2026</h3><p>Las facultades de fiscalización del SAT se refuerzan a partir de hoy, añadiendo controles de autenticidad más estrictos y — de forma notable — nueva responsabilidad penal por CFDI falsos o simulados. Esta es una escalada significativa respecto al marco sancionador puramente administrativo anterior. Vale la pena revisar ahora su documentación de defensa y sus procedimientos de cancelación, dado que el SAT puede solicitar evidencia de respaldo en tan solo 5 días hábiles.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.sat.gob.mx" target="_blank" rel="noopener">🔗 Fuente oficial: SAT — Servicio de Administración Tributaria</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-new-zealand-agency-einvoicing', 'es', 'Nueva Zelanda — los organismos gubernamentales de alto volumen deben enviar y recibir facturas electrónicas', 'Los organismos gubernamentales de alto volumen de Nueva Zelanda deben ahora enviar y recibir facturas electrónicas en formato PINT A-NZ.', '<h3>🇳🇿 Nueva Zelanda — los organismos gubernamentales de alto volumen deben enviar y recibir facturas electrónicas</h3><p>Los organismos que procesan más de 2.000 facturas comerciales nacionales al año deben ahora ser plenamente capaces de enviar y recibir facturas electrónicas estructuradas — usando el formato PINT A-NZ, obligatorio para la facturación electrónica gubernamental desde mayo de 2025 — y deben pagar el 95% de ellas en un plazo de 5 días hábiles. Si usted suministra a un organismo con este volumen, este es el momento en que las condiciones de pago deberían empezar realmente a mejorar.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.einvoicing.govt.nz" target="_blank" rel="noopener">🔗 Fuente oficial: einvoicing.govt.nz — MBIE</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-01-belgium-croatia-january-check-in', 'es', 'Seguimiento de enero', 'Un seguimiento de los mandatos de enero en Bélgica y Croacia, con un recordatorio de probar las integraciones de extremo a extremo, no solo confirmar la conectividad.', '<h3>Seguimiento de enero</h3><p>Un breve seguimiento del conjunto de seis países del mes pasado: si opera en Bélgica o Croacia y aún no ha probado su integración de extremo a extremo — no solo confirmado que está técnicamente conectada — este es un buen mes para hacerlo. Ambos mandatos conllevan sanciones reales por brechas que solo salen a la luz una vez que empieza a fluir un volumen real de facturas, y no en una prueba de entorno controlado.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-01-poland-ksef-large-taxpayers', 'es', 'Polonia — KSeF obligatorio para grandes contribuyentes', 'La plataforma de compensación KSeF de Polonia se vuelve obligatoria para los grandes contribuyentes con una facturación superior a 200 millones de PLN.', '<h3>🇵🇱 Polonia — KSeF obligatorio para grandes contribuyentes</h3><p>Los grandes contribuyentes con una facturación superior a 200 millones de PLN se convirtieron hoy en el primer grupo obligado a emitir facturas B2B a través de la plataforma de compensación Krajowy System e-Faktur (KSeF). Este es un modelo de compensación genuino — una factura no tiene efecto legal hasta que KSeF la ha validado y compensado, usando el esquema XML FA(3) enviado vía API. El resto sigue en abril, y los microempresarios desde enero de 2027; Polonia está implementando esto deliberadamente por escalones según el tamaño del contribuyente en lugar de activarlo todo a la vez, lo cual vale la pena saber si es una empresa pequeña que asume que ya está dentro del alcance.</p><p><strong>Qué significa esto para su equipo:</strong> si es un gran contribuyente polaco, esto ya no es un ejercicio de planificación. Confirme que su integración API con KSeF está realmente activa, y que el personal y cualquier autorización de emisor de terceros estén correctamente configurados — una autorización mal configurada es una de las causas más comunes de que la compensación falle silenciosamente en las primeras semanas.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ksef.mf.gov.pl/" target="_blank" rel="noopener">🔗 Fuente oficial: KSeF — Ministerio de Finanzas</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-01-chile-digital-boleta-delivery', 'es', 'Chile — entrega digital obligatoria sin impresora', 'Chile exige ahora la entrega digital de la boleta electrónica para los negocios sin capacidad de impresión en el punto de venta.', '<h3>🇨🇱 Chile — entrega digital obligatoria sin impresora</h3><p>Los negocios sin capacidad de impresión en el punto de venta deben ahora entregar la <em>boleta electrónica</em> digitalmente — por correo electrónico, SMS, WhatsApp, código QR o un canal electrónico equivalente — en lugar de simplemente omitir la entrega. Una norma pequeña, pero que cierra una brecha real para vendedores móviles, puestos temporales y operaciones de solo reparto que antes no tenían una vía claramente conforme cuando carecían de una impresora física.</p><p><strong>Qué significa esto para su equipo:</strong> si opera cualquier punto de venta sin impresora física — mercados, puestos temporales, configuraciones de solo reparto — confirme que realmente tiene hoy funcionando uno de estos canales electrónicos, no solo planeado para más adelante. Los negocios que sí tienen impresoras generalmente deben seguir entregando la representación impresa como antes.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.sii.cl" target="_blank" rel="noopener">🔗 Fuente oficial: Servicio de Impuestos Internos (SII)</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-01-saudi-arabia-zatca-wave-23', 'es', 'Arabia Saudita — ZATCA Fatoora Ola 23', 'La Ola 23 de ZATCA incorpora a las empresas con una facturación superior a 750.000 SAR a los requisitos de compensación en tiempo real de Fatoora.', '<h3>🇸🇦 Arabia Saudita — ZATCA Fatoora Ola 23</h3><p>Las empresas con una facturación sujeta a IVA superior a 750.000 SAR en 2022, 2023 o 2024 debían completar hoy la integración de la Fase 2 con la plataforma Fatoora para la compensación en tiempo real — lo que significa que las facturas llevan un UUID, un código QR y un sello criptográfico, enviados vía API para la compensación B2B/B2G en tiempo real. ZATCA continúa su implementación por olas — la Ola 24 sigue en junio, bajando el umbral a 375.000 SAR e incorporando a casi todas las empresas registradas a efectos de IVA del país.</p><p><strong>Qué significa esto para su equipo:</strong> si su facturación superó los 750.000 SAR en cualquiera de esos tres años de referencia, asuma que está en la Ola 23 salvo que ZATCA le haya indicado lo contrario — la notificación directa suele llegar unos seis meses antes, así que si no ha recibido nada y cree que debería haberlo hecho, vale la pena comprobarlo de forma proactiva en lugar de esperar una carta que ya podría estar retrasada.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://zatca.gov.sa" target="_blank" rel="noopener">🔗 Fuente oficial: ZATCA — Fatoora</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-01-brazil-cbs-ibs-validation', 'es', 'Brasil — comienza la validación CBS/IBS', 'Brasil comienza a validar rigurosamente los campos fiscales CBS/IBS, arriesgando el rechazo automático de facturas con datos faltantes o inconsistentes.', '<h3>🇧🇷 Brasil — comienza la validación CBS/IBS</h3><p>A medida que avanza la reforma del IVA dual de Brasil, los sistemas de autorización comenzaron hoy a validar rigurosamente los nuevos campos fiscales CBS e IBS en los documentos NF-e, NFC-e y NFS-e. Las facturas con datos faltantes o inconsistentes ahora corren el riesgo de un rechazo automático — todavía a tasas de prueba (0,9% / 0,1%), por lo que aún no hay impacto financiero, pero una factura rechazada puede igualmente retener el movimiento de mercancías independientemente de que la tasa sea nominal.</p><p><strong>Qué significa esto para su equipo:</strong> si aún no lo ha hecho, audite la salida de sus facturas para verificar los grupos de datos CBS/IBS/IS completos ahora, mientras las consecuencias son todavía bajas — esperar hasta que las tasas entren plenamente en vigor en agosto, según la Nota Técnica 2025.002-RTC, es dejarlo muy justo.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.nfe.fazenda.gov.br/portal/principal.aspx" target="_blank" rel="noopener">🔗 Fuente oficial: Portal Nacional da NF-e (SEFAZ)</a></p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">El detalle técnico completo de ambos casos está en sus respectivos análisis por país — Polonia y Brasil — si necesita el panorama completo para una reunión informativa.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-01-poland-ksef-universal', 'es', 'Polonia — el mandato KSeF se vuelve universal', 'El mandato KSeF de Polonia se vuelve universal para las empresas registradas a efectos de IVA, retirando por completo el antiguo proceso de notas de corrección.', '<h3>🇵🇱 Polonia — el mandato KSeF se vuelve universal</h3><p>A partir de hoy, el requisito KSeF de Polonia se extiende a esencialmente todas las empresas restantes registradas a efectos de IVA (los microempresarios siguen en una vía separada, incorporándose desde enero de 2027). A partir de esta fecha, una factura solo tiene fuerza legal una vez que KSeF la ha compensado — y las antiguas notas de corrección (<em>noty korygujące</em>) ya no son válidas en absoluto; las correcciones ahora deben pasar por el proceso de corrección estructurado del propio KSeF.</p><p><strong>Qué significa esto para su equipo:</strong> si tiene algún flujo de facturación B2B polaco que estaba previamente exento, confirme que su sistema está realmente generando facturas estructuradas FA(3) válidas ahora, no solo planeando hacerlo antes de fin de año. También vale la pena verificar: desde el 1 de agosto de 2026, los números de factura de KSeF también deben aparecer en las referencias de transferencia bancaria — un pequeño detalle que un equipo de tesorería puede pasar por alto fácilmente si no se le incluyó en la implementación de la facturación electrónica.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ksef.mf.gov.pl/" target="_blank" rel="noopener">🔗 Fuente oficial: KSeF — Ministerio de Finanzas</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-01-2027-wave-multi-country-outlook', 'es', 'Mirando hacia adelante: la ola de 2027 empieza a perfilarse', 'Una mirada hacia la ola de enero de 2027, en la que los contribuyentes restantes de Polonia, la implementación de VeriFactu en España y el mandato de Fase 1 de los EAU convergen en la misma ventana de puesta en marcha.', '<h3>Mirando hacia adelante: la ola de 2027 empieza a perfilarse</h3><p>Eslovaquia no está sola — los microempresarios restantes de Polonia, la implementación de VeriFactu en España y el mandato de Fase 1 de los EAU también apuntan a entradas en vigor en enero de 2027. Si su negocio toca más de uno de estos mercados, este es un punto razonable para iniciar una evaluación de preparación compartida en todos ellos, en lugar de tratar cada uno como un simulacro de incendio separado más adelante en el año.</p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">Si aún no lo ha visto, "Preparación para un mandato", en el menú de Educación, explica exactamente este tipo de planificación multipaís.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-01-slovakia-voluntary-testing', 'es', 'Eslovaquia — comienza el período de transición voluntario', 'Eslovaquia abre las pruebas voluntarias de su distintiva red Digital Postman de 5 esquinas antes de su mandato de enero de 2027.', '<h3>🇸🇰 Eslovaquia — comienza el período de transición voluntario</h3><p>Las empresas ya pueden registrarse para probar voluntariamente la facturación electrónica estructurada y el reporte antes del mandato de enero de 2027 de Eslovaquia, usando el distintivo modelo descentralizado de "5 esquinas" del país, construido sobre puntos de acceso certificados <em>Digital Postman</em> que funcionan sobre Peppol — una variante que no vemos replicada exactamente en ningún otro lugar que sigamos.</p><p><strong>Qué significa esto para su equipo:</strong> si comercia con contribuyentes de IVA eslovacos, esto vale genuinamente la pena hacerlo pronto en lugar de esperar. A partir de 2027, las deducciones del IVA soportado no podrán reclamarse sobre facturas entrantes no conformes — una consecuencia real para el flujo de caja, no solo un trámite. Probar ahora, mientras no hay sanción por hacerlo mal, es la forma económica de encontrar problemas de integración antes de que le cuesten dinero.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.financnasprava.sk/en/homepage" target="_blank" rel="noopener">🔗 Fuente oficial: Administración Financiera de la República Eslovaca</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-australia-peppol-threshold-preview', 'es', 'Australia — umbral Peppol del 30% para facturas federales', 'El umbral Peppol del 30% de Australia para las facturas federales entra en vigor el 1 de julio — un adelanto de lo que se viene y qué comprobar antes.', '<h3>🇦🇺 Australia — umbral Peppol del 30% para facturas federales</h3><p>A partir del 1 de julio, las Entidades no Corporativas de la Mancomunidad deben tener al menos el 30% de las facturas recibidas de proveedores fluyendo a través de la red Peppol, camino a la automatización completa para diciembre, con informes trimestrales de progreso a la Autoridad Peppol de Australia. Si usted suministra a organismos federales australianos, este es un buen momento para confirmar que su facturación está realmente habilitada para Peppol usando el formato PINT A-NZ — el único estándar admitido desde mayo de 2025 — y no solo técnicamente capacitada para ello.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing" target="_blank" rel="noopener">🔗 Fuente oficial: ATO — About eInvoicing</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-denmark-small-business-bookkeeping-preview', 'es', 'Dinamarca — las pequeñas empresas con sistemas propios se suman al mandato', 'Los requisitos digitales de la Ley de Contabilidad de Dinamarca se extienden a las pequeñas empresas con sistemas propios a partir del 1 de julio — vale la pena comprobar ahora su facturación frente al umbral.', '<h3>🇩🇰 Dinamarca — las pequeñas empresas con sistemas propios se suman al mandato</h3><p>Las pequeñas empresas y los autónomos que superen los 300.000 DKK de facturación durante dos años consecutivos, usando sistemas contables no registrados ("propios"), quedan plenamente sujetos a los requisitos digitales de la Ley de Contabilidad. Vale la pena comprobar si su facturación realmente ha superado ese umbral en los dos últimos ejercicios fiscales — es fácil asumir que sigue por debajo sin comprobar realmente las cifras.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://erhvervsstyrelsen.dk" target="_blank" rel="noopener">🔗 Fuente oficial: Erhvervsstyrelsen (Autoridad Empresarial Danesa)</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-malaysia-related-company-rule-preview', 'es', 'Malasia — las empresas relacionadas de grupos de RM1m+ entran ahora en el alcance', 'La regla de empresas relacionadas de MyInvois en Malasia entra en vigor el 1 de julio, incorporando a las filiales de grupos de RM1 millón o más, independientemente de su propia facturación individual.', '<h3>🇲🇾 Malasia — las empresas relacionadas de grupos de RM1m+ entran ahora en el alcance</h3><p>Esta es la que con más probabilidad puede pillar desprevenida a una empresa: incluso si sus propios ingresos están muy por debajo de los umbrales de Malasia, si es una filial o empresa relacionada de un grupo con RM1 millón o más de facturación, está dentro del alcance a partir del 1 de julio independientemente de su propio tamaño individual. La estructura del grupo, no la facturación individual, es lo que determina si queda incluida aquí.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Fuente oficial: LHDN — MyInvois / e-Invoice</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-uae-voluntary-pilot-preview', 'es', 'EAU — se abre el piloto voluntario de facturación electrónica', 'Los EAU abren un piloto voluntario de facturación electrónica a partir del 1 de julio, permitiendo a las empresas probar la conectividad ASP antes de las fases obligatorias de enero de 2027.', '<h3>🇦🇪 EAU — se abre el piloto voluntario de facturación electrónica</h3><p>Antes de las fases obligatorias que comienzan en enero de 2027, los EAU abren la participación voluntaria en esta fecha — permitiendo a las empresas probar la conectividad con un Proveedor de Servicios Acreditado y el formato PINT AE sin riesgo antes de que se apliquen sanciones. Dado que el plazo para el nombramiento del ASP para las grandes empresas vence en octubre, aprovechar bien esta ventana piloto antes de esa fecha es genuinamente el orden sensato de hacer las cosas.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://mof.gov.ae/en/about-ministry/mof-initiatives/einvoicing/" target="_blank" rel="noopener">🔗 Fuente oficial: Ministerio de Finanzas de los EAU — eInvoicing</a></p><p><strong>Qué significa esto para su equipo:</strong> si alguno de estos cuatro casos le aplica, este es el mes para terminar realmente las pruebas, no para empezarlas. El 1 de julio llega rápido, y ninguno de estos cuatro da mucho margen de gracia una vez que pasa la fecha.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-australia-peppol-threshold-live', 'es', 'Australia — el umbral Peppol del 30% ya está en vigor', 'El umbral Peppol del 30% de Australia para las facturas federales ya está en vigor, con informes trimestrales de progreso a la Autoridad Peppol de Australia.', '<h3>🇦🇺 Australia — el umbral Peppol del 30% ya está en vigor</h3><p>Los organismos federales deben tener ahora al menos el 30% de las facturas recibidas de proveedores fluyendo a través de Peppol, con informes trimestrales de progreso a la Autoridad Peppol de Australia. Si suministra en este espacio y no ha confirmado que su facturación está habilitada para Peppol, eso ya no es una tarea para "pronto" — es una brecha de cumplimiento activa.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing" target="_blank" rel="noopener">🔗 Fuente oficial: ATO — About eInvoicing</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-denmark-small-business-bookkeeping-live', 'es', 'Dinamarca — las pequeñas empresas con sistemas propios ya están dentro del alcance', 'Los requisitos digitales de la Ley de Contabilidad de Dinamarca ya están activos para las pequeñas empresas con sistemas propios por encima del umbral de 300.000 DKK.', '<h3>🇩🇰 Dinamarca — las pequeñas empresas con sistemas propios ya están dentro del alcance</h3><p>Los requisitos digitales de la Ley de Contabilidad ya se aplican a las pequeñas empresas y autónomos que superan el umbral de dos años de 300.000 DKK usando sistemas no registrados, incluido un requisito de mantener registros digitales durante 5 años con copia de seguridad externa automatizada.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://erhvervsstyrelsen.dk" target="_blank" rel="noopener">🔗 Fuente oficial: Erhvervsstyrelsen (Autoridad Empresarial Danesa)</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-malaysia-related-company-rule-live', 'es', 'Malasia — la regla de empresas relacionadas ya está activa', 'La regla de empresas relacionadas de MyInvois en Malasia ya está activa, incorporando al alcance a las filiales de grupos de RM1 millón o más.', '<h3>🇲🇾 Malasia — la regla de empresas relacionadas ya está activa</h3><p>Las filiales y empresas relacionadas de grupos de RM1 millón o más ya están dentro del alcance de MyInvois, independientemente de su propia facturación individual. Vale la pena hacer hoy una comprobación final de la estructura de su grupo si aún no ha confirmado su situación.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Fuente oficial: LHDN — MyInvois / e-Invoice</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-poland-bank-transfer-reference-preview', 'es', 'Lo que estamos siguiendo de cara a agosto', 'Un adelanto del requisito de Polonia, a partir del 1 de agosto, de incluir los números de factura de KSeF en las referencias de transferencia bancaria — un detalle fácil de pasar por alto para los equipos de tesorería.', '<h3>Lo que estamos siguiendo de cara a agosto</h3><p>El requisito de Polonia de incluir el número de factura de KSeF en las transferencias bancarias entra en vigor el 1 de agosto — un detalle pequeño pero fácil de pasar por alto si su equipo de tesorería/pagos aún no está integrado en la implementación de la facturación electrónica. Lo cubriremos correctamente en el próximo número, con el enlace oficial de KSeF como siempre.</p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">Como siempre, los análisis por país tienen el detalle técnico completo detrás de cada uno de estos temas si necesita informar a su equipo más allá de este resumen.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-uae-voluntary-pilot-live', 'es', 'EAU — el piloto voluntario ya está abierto', 'El piloto voluntario de facturación electrónica de los EAU ya está abierto, antes de las fases obligatorias de enero de 2027 y del plazo de octubre para el nombramiento del ASP en las grandes empresas.', '<h3>🇦🇪 EAU — el piloto voluntario ya está abierto</h3><p>Las empresas ya pueden probar la conectividad con un Proveedor de Servicios Acreditado y el formato PINT AE antes de las fases obligatorias de enero de 2027 — genuinamente vale la pena empezar de inmediato dado que el plazo para el nombramiento del ASP en las grandes empresas vence en octubre.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://mof.gov.ae/en/about-ministry/mof-initiatives/einvoicing/" target="_blank" rel="noopener">🔗 Fuente oficial: Ministerio de Finanzas de los EAU — eInvoicing</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-belgium-mandatory-b2b-peppol', 'de', 'Belgien — verpflichtende B2B-E-Rechnung über Peppol', 'Belgiens B2B-E-Invoicing-Vorgabe tritt in Kraft und verlangt Peppol BIS 3.0 für alle inländischen umsatzsteuerpflichtigen Transaktionen.', '<h3>🇧🇪 Belgien — verpflichtende B2B-E-Rechnung über Peppol</h3><p>Strukturierte E-Rechnungen sind ab heute für inländische B2B-Transaktionen zwischen umsatzsteuerpflichtigen belgischen Unternehmen verpflichtend, unter Verwendung von Peppol BIS Billing 3.0 / EN 16931. PDF- und Papierrechnungen sind ab heute nicht mehr gültig. Eine dreimonatige administrative Toleranzfrist läuft bis zum 1. April, danach gilt ein gestuftes Sanktionsregime (1.500 € / 3.000 € / 5.000 € pro Verstoß) — dieses Zeitfenster lohnt sich also wirklich, um verbleibende Lücken zu schließen, statt es nur abzuwarten.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium" target="_blank" rel="noopener">🔗 Offizielle Quelle: EU Digital Building Blocks — Belgien</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-brazil-cbs-ibs-test-fields', 'de', 'Brasilien — CBS/IBS-Testfelder erforderlich', 'Brasiliens Doppel-Umsatzsteuerreform beginnt und verlangt neue CBS/IBS-Testfelder auf NF-e-, NFC-e- und NFS-e-Dokumenten.', '<h3>🇧🇷 Brasilien — CBS/IBS-Testfelder erforderlich</h3><p>Mit Beginn von Brasiliens Doppel-Umsatzsteuerreform müssen elektronische Steuerdokumente (NF-e, NFC-e, NFS-e) nun die neuen CBS- und IBS-Felder mit Testsätzen von 0,9 % bzw. 0,1 % enthalten. Bei diesen Testsätzen gibt es noch keine finanziellen Auswirkungen, aber die gesetzliche Pflicht zur korrekten Angabe der Daten gilt bereits — und die Validierung wird ab April deutlich strenger.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.nfe.fazenda.gov.br/portal/principal.aspx" target="_blank" rel="noopener">🔗 Offizielle Quelle: Portal Nacional da NF-e (SEFAZ)</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-croatia-fiskalizacija-2', 'de', 'Kroatien — Fiskalizacija 2.0 geht live', 'Kroatiens Fiskalizacija 2.0 schreibt strukturierte B2B-E-Rechnungen und Echtzeit-E-Reporting für alle umsatzsteuerpflichtigen Steuerpflichtigen vor.', '<h3>🇭🇷 Kroatien — Fiskalizacija 2.0 geht live</h3><p>Kroatiens bislang größte E-Invoicing-Reform: strukturierte Ausstellung, Empfang und Echtzeit-E-Reporting sind nun für alle umsatzsteuerpflichtigen, in Kroatien niedergelassenen Steuerpflichtigen verpflichtend — zusätzlich zur bereits seit 2019 geltenden B2G-Vorgabe. Dies umfasst einen 5-tägigen Fiskalisierungsworkflow auf Käuferseite und monatliches E-Reporting bis zum 20. jedes Monats, plus eine 11-jährige Archivierungspflicht für die originalen XML-Rechnungen.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://porezna-uprava.gov.hr/en" target="_blank" rel="noopener">🔗 Offizielle Quelle: Porezna uprava (Kroatische Steuerverwaltung)</a></p><p><strong>Was das für Ihr Team bedeutet:</strong> Wenn Sie in einem dieser sechs Märkte tätig sind, ist jetzt der Moment, zu bestätigen — nicht anzunehmen —, dass alles, was über die Feiertage live gegangen ist, in der Produktion tatsächlich korrekt funktioniert und nicht nur konfiguriert, aber ungetestet ist.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-malaysia-myinvois-phase-4', 'de', 'Malaysia — Phase 4 von MyInvois beginnt', 'MyInvois Phase 4 bringt Unternehmen mit einem Umsatz von RM1–5 Millionen in Malaysias E-Invoicing-Vorgabe.', '<h3>🇲🇾 Malaysia — Phase 4 von MyInvois beginnt</h3><p>Unternehmen mit einem Jahresumsatz zwischen RM1 Million und RM5 Millionen treten heute in die Vorgabe ein, mit einer Erleichterungsfrist bei Sanktionen für Übermittlungsfehler bis Ende 2027. Einzelne E-Rechnungen über RM10.000 sind nun verpflichtend — konsolidierte Rechnungsstellung ist für Beträge dieser Größenordnung nicht mehr zulässig.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Offizielle Quelle: LHDN — MyInvois / e-Invoice</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-mexico-2026-tax-reform', 'de', 'Mexiko — Steuerreform 2026 tritt in Kraft', 'Mexikos Steuerreform 2026 stärkt die Durchsetzungsbefugnisse der SAT und führt eine strafrechtliche Haftung für falsche CFDIs ein.', '<h3>🇲🇽 Mexiko — Steuerreform 2026 tritt in Kraft</h3><p>Die Durchsetzungsbefugnisse der SAT werden ab heute gestärkt, mit strengeren Echtheitsprüfungen und — bemerkenswert — neuer strafrechtlicher Haftung für falsche oder simulierte CFDIs. Dies ist eine deutliche Verschärfung gegenüber dem bisher rein verwaltungsrechtlichen Sanktionsrahmen. Es lohnt sich, jetzt Ihre Verteidigungsdokumentation und Stornierungsverfahren zu überprüfen, da die SAT unterstützende Nachweise innerhalb von nur 5 Werktagen anfordern kann.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.sat.gob.mx" target="_blank" rel="noopener">🔗 Offizielle Quelle: SAT — Servicio de Administración Tributaria</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-new-zealand-agency-einvoicing', 'de', 'Neuseeland — Regierungsbehörden mit hohem Volumen müssen E-Rechnungen senden und empfangen können', 'Neuseeländische Regierungsbehörden mit hohem Volumen müssen nun E-Rechnungen im Format PINT A-NZ senden und empfangen können.', '<h3>🇳🇿 Neuseeland — Regierungsbehörden mit hohem Volumen müssen E-Rechnungen senden und empfangen können</h3><p>Behörden, die jährlich mehr als 2.000 inländische Handelsrechnungen verarbeiten, müssen nun vollständig in der Lage sein, strukturierte E-Rechnungen zu senden und zu empfangen — im Format PINT A-NZ, das seit Mai 2025 für die staatliche E-Rechnungsstellung verpflichtend ist — und müssen 95 % davon innerhalb von 5 Werktagen bezahlen. Wenn Sie eine Behörde in diesem Umfang beliefern, ist dies der Moment, in dem sich die Zahlungsbedingungen tatsächlich verbessern sollten.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.einvoicing.govt.nz" target="_blank" rel="noopener">🔗 Offizielle Quelle: einvoicing.govt.nz — MBIE</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-01-belgium-croatia-january-check-in', 'de', 'Rückblick auf Januar', 'Ein Nachtrag zu den Januar-Vorgaben in Belgien und Kroatien, mit der Erinnerung, Integrationen tatsächlich Ende-zu-Ende zu testen, nicht nur die Konnektivität zu bestätigen.', '<h3>Rückblick auf Januar</h3><p>Ein kurzer Nachtrag zum Sechs-Länder-Cluster des letzten Monats: Wenn Sie in Belgien oder Kroatien tätig sind und Ihre Integration noch nicht Ende-zu-Ende getestet haben — nicht nur bestätigt, dass sie technisch verbunden ist —, ist dies ein guter Monat dafür. Beide Vorgaben bringen echte Sanktionen für Lücken mit sich, die erst sichtbar werden, sobald echtes Rechnungsvolumen hindurchfließt, statt in einem Sandbox-Test.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-01-poland-ksef-large-taxpayers', 'de', 'Polen — KSeF für Großsteuerzahler verpflichtend', 'Polens KSeF-Freigabeplattform wird für Großsteuerzahler mit einem Umsatz über 200 Millionen PLN verpflichtend.', '<h3>🇵🇱 Polen — KSeF für Großsteuerzahler verpflichtend</h3><p>Großsteuerzahler mit einem Umsatz über 200 Millionen PLN waren heute die erste Gruppe, die B2B-Rechnungen über die Freigabeplattform Krajowy System e-Faktur (KSeF) ausstellen musste. Dies ist ein echtes Freigabemodell — eine Rechnung hat keine Rechtswirkung, bis KSeF sie über das per API übermittelte FA(3)-XML-Schema validiert und freigegeben hat. Alle anderen folgen im April, Kleinstunternehmer ab Januar 2027; Polen führt dies bewusst gestaffelt nach Unternehmensgröße ein, statt alles auf einmal zu aktivieren — wichtig zu wissen, wenn Sie als kleineres Unternehmen annehmen, bereits im Anwendungsbereich zu sein.</p><p><strong>Was das für Ihr Team bedeutet:</strong> Wenn Sie ein großer polnischer Steuerzahler sind, ist dies keine Planungsübung mehr. Bestätigen Sie, dass Ihre API-Integration mit KSeF tatsächlich live ist und dass Mitarbeiter sowie etwaige Drittanbieter-Ausstellungsberechtigungen korrekt konfiguriert sind — eine falsch konfigurierte Berechtigung ist einer der häufigsten Gründe, warum die Freigabe in den ersten Wochen stillschweigend fehlschlägt.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ksef.mf.gov.pl/" target="_blank" rel="noopener">🔗 Offizielle Quelle: KSeF — Finanzministerium</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-01-chile-digital-boleta-delivery', 'de', 'Chile — digitale Zustellung ohne Drucker erforderlich', 'Chile verlangt nun die digitale Zustellung der boleta electrónica für Unternehmen ohne Drucker am Verkaufsort.', '<h3>🇨🇱 Chile — digitale Zustellung ohne Drucker erforderlich</h3><p>Unternehmen ohne Drucker am Verkaufsort müssen die <em>boleta electrónica</em> nun digital zustellen — per E-Mail, SMS, WhatsApp, QR-Code oder einen gleichwertigen elektronischen Kanal — statt die Zustellung schlicht auszulassen. Eine kleine Regel, die aber eine echte Lücke für mobile Verkäufer, Pop-ups und reine Lieferbetriebe schließt, die zuvor ohne physischen Drucker keinen klar konformen Weg hatten.</p><p><strong>Was das für Ihr Team bedeutet:</strong> Wenn Sie einen Verkaufspunkt ohne physischen Drucker betreiben — Märkte, Pop-ups, reine Lieferaufbauten —, bestätigen Sie, dass einer dieser elektronischen Kanäle heute tatsächlich funktioniert, nicht nur für später geplant ist. Unternehmen mit Druckern müssen die gedruckte Darstellung im Allgemeinen weiterhin wie bisher zustellen.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.sii.cl" target="_blank" rel="noopener">🔗 Offizielle Quelle: Servicio de Impuestos Internos (SII)</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-01-saudi-arabia-zatca-wave-23', 'de', 'Saudi-Arabien — ZATCA Fatoora Welle 23', 'ZATCAs Welle 23 bringt Unternehmen mit einem Umsatz über 750.000 SAR in die Echtzeit-Freigabepflichten von Fatoora.', '<h3>🇸🇦 Saudi-Arabien — ZATCA Fatoora Welle 23</h3><p>Unternehmen mit einem umsatzsteuerpflichtigen Umsatz über 750.000 SAR in den Jahren 2022, 2023 oder 2024 mussten die Phase-2-Integration mit der Fatoora-Plattform für die Echtzeit-Freigabe ab heute abschließen — das heißt, Rechnungen tragen eine UUID, einen QR-Code und einen kryptografischen Stempel, übermittelt per API für die B2B/B2G-Echtzeitfreigabe. ZATCA setzt seinen wellenbasierten Rollout fort — Welle 24 folgt im Juni und senkt die Schwelle auf 375.000 SAR, wodurch fast jedes umsatzsteuerpflichtige Unternehmen im Land einbezogen wird.</p><p><strong>Was das für Ihr Team bedeutet:</strong> Wenn Ihr Umsatz in einem dieser drei Referenzjahre 750.000 SAR überschritten hat, gehen Sie davon aus, dass Sie in Welle 23 sind, sofern ZATCA Ihnen nichts anderes mitgeteilt hat — die direkte Benachrichtigung erfolgt typischerweise rund sechs Monate im Voraus. Wenn Sie also nichts gehört haben, aber glauben, dass Sie es sollten, lohnt es sich, proaktiv nachzufragen, statt auf einen möglicherweise bereits verspäteten Brief zu warten.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://zatca.gov.sa" target="_blank" rel="noopener">🔗 Offizielle Quelle: ZATCA — Fatoora</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-01-brazil-cbs-ibs-validation', 'de', 'Brasilien — CBS/IBS-Validierung beginnt', 'Brasilien beginnt mit der rigorosen Validierung der CBS/IBS-Steuerfelder und riskiert die automatische Ablehnung von Rechnungen mit fehlenden oder inkonsistenten Daten.', '<h3>🇧🇷 Brasilien — CBS/IBS-Validierung beginnt</h3><p>Im Zuge von Brasiliens Doppel-Umsatzsteuerreform begannen die Genehmigungssysteme heute mit der rigorosen Validierung der neuen CBS- und IBS-Steuerfelder auf NF-e-, NFC-e- und NFS-e-Dokumenten. Rechnungen mit fehlenden oder inkonsistenten Daten riskieren nun die automatische Ablehnung — noch zu Testsätzen (0,9 % / 0,1 %), also noch ohne finanzielle Auswirkung, aber eine abgelehnte Rechnung kann die Warenbewegung dennoch aufhalten, unabhängig davon, dass der Satz nominal ist.</p><p><strong>Was das für Ihr Team bedeutet:</strong> Prüfen Sie, falls noch nicht geschehen, jetzt Ihre Rechnungsausgabe auf vollständige CBS-/IBS-/IS-Datengruppen, solange die Einsätze noch niedrig sind — bis August zu warten, wenn die Sätze gemäß Technischer Note 2025.002-RTC voll in Kraft treten, wird knapp.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.nfe.fazenda.gov.br/portal/principal.aspx" target="_blank" rel="noopener">🔗 Offizielle Quelle: Portal Nacional da NF-e (SEFAZ)</a></p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">Vollständige technische Details zu beiden Themen finden Sie in den jeweiligen Länderanalysen — Polen und Brasilien —, falls Sie das komplette Bild für ein Briefing benötigen.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-01-poland-ksef-universal', 'de', 'Polen — KSeF-Vorgabe wird universell', 'Polens KSeF-Vorgabe wird für umsatzsteuerpflichtige Unternehmen universell und schafft den alten Korrekturnotiz-Prozess vollständig ab.', '<h3>🇵🇱 Polen — KSeF-Vorgabe wird universell</h3><p>Ab heute erstreckt sich Polens KSeF-Anforderung auf im Wesentlichen alle verbleibenden umsatzsteuerpflichtigen Unternehmen (Kleinstunternehmer bleiben auf einem separaten Pfad und kommen ab Januar 2027 hinzu). Ab diesem Datum hat eine Rechnung nur noch Rechtswirkung, sobald KSeF sie freigegeben hat — und die alten Korrekturnotizen (<em>noty korygujące</em>) sind überhaupt nicht mehr gültig; Korrekturen müssen nun über den eigenen strukturierten Korrekturprozess von KSeF laufen.</p><p><strong>Was das für Ihr Team bedeutet:</strong> Wenn Sie einen polnischen B2B-Rechnungsfluss haben, der zuvor ausgenommen war, bestätigen Sie, dass Ihr System jetzt tatsächlich gültige, strukturierte FA(3)-Rechnungen erzeugt, statt dies erst bis Jahresende zu planen. Ebenfalls wert, es zu prüfen: Ab dem 1. August 2026 müssen KSeF-Rechnungsnummern auch bei Banküberweisungsreferenzen erscheinen — ein kleines Detail, das ein Treasury-Team leicht übersehen kann, wenn es nicht in den E-Invoicing-Rollout eingebunden war.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ksef.mf.gov.pl/" target="_blank" rel="noopener">🔗 Offizielle Quelle: KSeF — Finanzministerium</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-01-2027-wave-multi-country-outlook', 'de', 'Ausblick: die 2027er-Welle nimmt Gestalt an', 'Ein Ausblick auf die Januar-2027-Welle, da Polens verbleibende Steuerzahler, Spaniens VeriFactu-Rollout und die Phase-1-Vorgabe der VAE alle auf dasselbe Go-Live-Fenster zulaufen.', '<h3>Ausblick: die 2027er-Welle nimmt Gestalt an</h3><p>Die Slowakei steht nicht allein da — Polens verbleibende Kleinstunternehmer, Spaniens VeriFactu-Rollout und die Phase-1-Vorgabe der VAE zielen ebenfalls alle auf einen Go-Live im Januar 2027. Wenn Ihr Unternehmen mehr als einen dieser Märkte berührt, ist dies ein sinnvoller Zeitpunkt, um eine gemeinsame Bereitschaftsbewertung über alle hinweg zu starten, statt jeden später im Jahr als separaten Feuerwehreinsatz zu behandeln.</p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">Falls noch nicht gesehen: "Vorbereitung auf eine Vorgabe" im Menü Wissen behandelt genau diese Art der länderübergreifenden Planung.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-01-slovakia-voluntary-testing', 'de', 'Slowakei — freiwillige Übergangsphase beginnt', 'Die Slowakei öffnet freiwillige Tests ihres unverwechselbaren 5-Corner-Netzwerks Digital Postman vor ihrer Vorgabe im Januar 2027.', '<h3>🇸🇰 Slowakei — freiwillige Übergangsphase beginnt</h3><p>Unternehmen können sich nun registrieren, um strukturierte E-Rechnungen und Meldungen vor der Vorgabe der Slowakei im Januar 2027 freiwillig zu testen, unter Verwendung des unverwechselbaren dezentralen "5-Corner"-Modells des Landes, das auf zertifizierten <em>Digital-Postman</em>-Zugangspunkten über Peppol aufbaut — eine Variante, die wir sonst nirgendwo, was wir erfassen, exakt repliziert sehen.</p><p><strong>Was das für Ihr Team bedeutet:</strong> Wenn Sie mit slowakischen umsatzsteuerpflichtigen Unternehmen handeln, lohnt es sich wirklich, dies frühzeitig zu tun, statt zu warten. Ab 2027 können Vorsteuerabzüge auf nicht konforme eingehende Rechnungen nicht mehr geltend gemacht werden — eine echte Cashflow-Konsequenz, nicht nur eine Formalität. Jetzt zu testen, solange es keine Sanktion für Fehler gibt, ist der günstige Weg, Integrationsprobleme zu finden, bevor sie Geld kosten.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.financnasprava.sk/en/homepage" target="_blank" rel="noopener">🔗 Offizielle Quelle: Finanzverwaltung der Slowakischen Republik</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-australia-peppol-threshold-preview', 'de', 'Australien — 30 %-Peppol-Schwelle für Bundesrechnungen', 'Australiens 30 %-Peppol-Schwelle für Bundesrechnungen tritt am 1. Juli in Kraft — ein Vorausblick auf das Kommende und was vorher zu prüfen ist.', '<h3>🇦🇺 Australien — 30 %-Peppol-Schwelle für Bundesrechnungen</h3><p>Ab dem 1. Juli müssen nicht-körperschaftliche Bundeseinrichtungen mindestens 30 % der erhaltenen Lieferantenrechnungen über das Peppol-Netzwerk abwickeln, auf dem Weg zur vollständigen Automatisierung bis Dezember, mit vierteljährlicher Fortschrittsberichterstattung an die australische Peppol-Behörde. Wenn Sie australische Bundesbehörden beliefern, ist dies ein guter Moment, um zu bestätigen, dass Ihre Rechnungsstellung tatsächlich Peppol-fähig ist und das Format PINT A-NZ verwendet — den seit Mai 2025 einzig unterstützten Standard — und nicht nur technisch dazu in der Lage ist.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing" target="_blank" rel="noopener">🔗 Offizielle Quelle: ATO — About eInvoicing</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-denmark-small-business-bookkeeping-preview', 'de', 'Dänemark — kleine Unternehmen mit eigenen Systemen treten der Vorgabe bei', 'Die digitalen Anforderungen des dänischen Buchführungsgesetzes erstrecken sich ab dem 1. Juli auf kleine Unternehmen mit eigenen Systemen — es lohnt sich, jetzt Ihren Umsatz gegen die Schwelle zu prüfen.', '<h3>🇩🇰 Dänemark — kleine Unternehmen mit eigenen Systemen treten der Vorgabe bei</h3><p>Kleine Unternehmen und Einzelunternehmer, die die Schwelle von 300.000 DKK Umsatz in zwei aufeinanderfolgenden Jahren überschreiten und nicht registrierte ("eigene") Buchhaltungssysteme verwenden, unterliegen nun vollständig den digitalen Anforderungen des Buchführungsgesetzes. Es lohnt sich zu prüfen, ob Ihr Umsatz diese Schwelle in den letzten zwei Geschäftsjahren tatsächlich überschritten hat — es ist leicht anzunehmen, noch darunter zu liegen, ohne die Zahlen tatsächlich zu prüfen.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://erhvervsstyrelsen.dk" target="_blank" rel="noopener">🔗 Offizielle Quelle: Erhvervsstyrelsen (Dänische Wirtschaftsbehörde)</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-malaysia-related-company-rule-preview', 'de', 'Malaysia — verbundene Unternehmen von RM1-Mio.-Gruppen nun im Anwendungsbereich', 'Malaysias MyInvois-Regel für verbundene Unternehmen tritt am 1. Juli in Kraft und erfasst Tochtergesellschaften von Gruppen mit RM1 Million oder mehr Umsatz, unabhängig von deren eigenem Umsatz.', '<h3>🇲🇾 Malaysia — verbundene Unternehmen von RM1-Mio.-Gruppen nun im Anwendungsbereich</h3><p>Dies ist die Regel, die ein Unternehmen am ehesten überraschen dürfte: Selbst wenn Ihr eigener Umsatz weit unter Malaysias Schwellenwerten liegt, sind Sie ab dem 1. Juli im Anwendungsbereich, wenn Sie eine Tochtergesellschaft oder ein verbundenes Unternehmen einer Gruppe mit RM1 Million oder mehr Umsatz sind — unabhängig von Ihrer eigenen individuellen Größe. Die Gruppenstruktur, nicht der eigenständige Umsatz, entscheidet hier über die Erfassung.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Offizielle Quelle: LHDN — MyInvois / e-Invoice</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-uae-voluntary-pilot-preview', 'de', 'VAE — freiwilliges E-Invoicing-Pilotprojekt startet', 'Die VAE eröffnen ab dem 1. Juli ein freiwilliges E-Invoicing-Pilotprojekt, das Unternehmen die Möglichkeit gibt, die ASP-Konnektivität vor den verpflichtenden Phasen ab Januar 2027 zu testen.', '<h3>🇦🇪 VAE — freiwilliges E-Invoicing-Pilotprojekt startet</h3><p>Vor den verpflichtenden Phasen, die im Januar 2027 beginnen, öffnen die VAE ab diesem Datum die freiwillige Teilnahme — Unternehmen können risikofrei die Konnektivität mit einem akkreditierten Dienstleister und das Format PINT AE testen, bevor Sanktionen greifen. Da die Frist zur Benennung des ASP für große Unternehmen im Oktober liegt, ist es genuin sinnvoll, dieses Pilotfenster gut vorher zu nutzen.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://mof.gov.ae/en/about-ministry/mof-initiatives/einvoicing/" target="_blank" rel="noopener">🔗 Offizielle Quelle: VAE-Finanzministerium — eInvoicing</a></p><p><strong>Was das für Ihr Team bedeutet:</strong> Wenn einer dieser vier Punkte auf Sie zutrifft, ist dies der Monat, um das Testen tatsächlich abzuschließen, nicht erst zu beginnen. Der 1. Juli kommt schnell, und keiner dieser vier Fälle bietet nach Ablauf des Datums viel Kulanzfrist.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-australia-peppol-threshold-live', 'de', 'Australien — 30 %-Peppol-Schwelle nun in Kraft', 'Australiens 30 %-Peppol-Schwelle für Bundesrechnungen ist nun in Kraft, mit vierteljährlicher Fortschrittsberichterstattung an die australische Peppol-Behörde.', '<h3>🇦🇺 Australien — 30 %-Peppol-Schwelle nun in Kraft</h3><p>Bundesbehörden müssen nun mindestens 30 % der erhaltenen Lieferantenrechnungen über Peppol abwickeln, mit vierteljährlicher Fortschrittsberichterstattung an die australische Peppol-Behörde. Wenn Sie in diesem Bereich liefern und noch nicht bestätigt haben, dass Ihre Rechnungsstellung Peppol-fähig ist, ist das keine "Bald"-Aufgabe mehr — es ist eine aktive Compliance-Lücke.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing" target="_blank" rel="noopener">🔗 Offizielle Quelle: ATO — About eInvoicing</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-denmark-small-business-bookkeeping-live', 'de', 'Dänemark — kleine Unternehmen mit eigenen Systemen nun im Anwendungsbereich', 'Die digitalen Anforderungen des dänischen Buchführungsgesetzes gelten nun aktiv für kleine Unternehmen mit eigenen Systemen über der Schwelle von 300.000 DKK.', '<h3>🇩🇰 Dänemark — kleine Unternehmen mit eigenen Systemen nun im Anwendungsbereich</h3><p>Die digitalen Anforderungen des Buchführungsgesetzes gelten nun für kleine Unternehmen und Einzelunternehmer über der zweijährigen Schwelle von 300.000 DKK, die nicht registrierte Systeme verwenden, einschließlich der Pflicht, 5 Jahre lang digitale Aufzeichnungen mit automatisierter Offsite-Sicherung zu führen.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://erhvervsstyrelsen.dk" target="_blank" rel="noopener">🔗 Offizielle Quelle: Erhvervsstyrelsen (Dänische Wirtschaftsbehörde)</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-malaysia-related-company-rule-live', 'de', 'Malaysia — Regel für verbundene Unternehmen nun aktiv', 'Malaysias MyInvois-Regel für verbundene Unternehmen ist nun aktiv und erfasst Tochtergesellschaften von Gruppen mit RM1 Million oder mehr Umsatz.', '<h3>🇲🇾 Malaysia — Regel für verbundene Unternehmen nun aktiv</h3><p>Tochtergesellschaften und verbundene Unternehmen von Gruppen mit RM1 Million oder mehr Umsatz fallen nun unabhängig von ihrem eigenen individuellen Umsatz in den Anwendungsbereich von MyInvois. Es lohnt sich, heute eine abschließende Prüfung Ihrer Gruppenstruktur vorzunehmen, falls Sie Ihren Status noch nicht bestätigt haben.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Offizielle Quelle: LHDN — MyInvois / e-Invoice</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-poland-bank-transfer-reference-preview', 'de', 'Was wir für August im Blick behalten', 'Ein Vorausblick auf Polens Anforderung ab dem 1. August, KSeF-Rechnungsnummern auf Banküberweisungsreferenzen anzugeben — ein Detail, das Treasury-Teams leicht übersehen.', '<h3>Was wir für August im Blick behalten</h3><p>Polens Anforderung, die KSeF-Rechnungsnummer bei Banküberweisungen anzugeben, tritt am 1. August in Kraft — ein kleines, aber leicht zu übersehendes Detail, wenn Ihr Treasury-/Zahlungsteam noch nicht in den E-Invoicing-Rollout eingebunden ist. Wir behandeln es in der nächsten Ausgabe ausführlich, mit dem offiziellen KSeF-Link wie immer.</p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">Wie immer enthalten die Länderanalysen die vollständigen technischen Details zu jedem dieser Themen, falls Sie Ihr Team über diese Zusammenfassung hinaus briefen müssen.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-uae-voluntary-pilot-live', 'de', 'VAE — freiwilliges Pilotprojekt nun geöffnet', 'Das freiwillige E-Invoicing-Pilotprojekt der VAE ist nun geöffnet, vor den verpflichtenden Phasen ab Januar 2027 und der Oktober-Frist zur ASP-Benennung für größere Unternehmen.', '<h3>🇦🇪 VAE — freiwilliges Pilotprojekt nun geöffnet</h3><p>Unternehmen können nun die Konnektivität mit einem akkreditierten Dienstleister und das Format PINT AE vor den verpflichtenden Phasen ab Januar 2027 testen — es lohnt sich genuin, sofort zu beginnen, da die Frist zur ASP-Benennung für größere Unternehmen im Oktober liegt.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://mof.gov.ae/en/about-ministry/mof-initiatives/einvoicing/" target="_blank" rel="noopener">🔗 Offizielle Quelle: VAE-Finanzministerium — eInvoicing</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-belgium-mandatory-b2b-peppol', 'fr', 'Belgique — facturation électronique B2B obligatoire via Peppol', 'L''obligation de facturation électronique B2B en Belgique entre en vigueur, exigeant Peppol BIS 3.0 pour toutes les transactions nationales entre assujettis à la TVA.', '<h3>🇧🇪 Belgique — facturation électronique B2B obligatoire via Peppol</h3><p>La facturation électronique structurée est désormais obligatoire pour les transactions B2B nationales entre entreprises belges assujetties à la TVA, en utilisant Peppol BIS Billing 3.0 / EN 16931. Les factures PDF et papier ne sont plus valables à compter d''aujourd''hui. Une période de tolérance administrative de trois mois court jusqu''au 1er avril, après quoi un régime de sanctions progressives (1 500 € / 3 000 € / 5 000 € par infraction) s''applique — cette fenêtre vaut donc vraiment la peine d''être utilisée pour combler les lacunes restantes, pas seulement pour attendre que ça passe.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium" target="_blank" rel="noopener">🔗 Source officielle : EU Digital Building Blocks — Belgique</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-brazil-cbs-ibs-test-fields', 'fr', 'Brésil — champs de test CBS/IBS requis', 'La réforme de la double TVA au Brésil commence, exigeant de nouveaux champs de test CBS/IBS sur les documents NF-e, NFC-e et NFS-e.', '<h3>🇧🇷 Brésil — champs de test CBS/IBS requis</h3><p>Alors que débute la réforme de la double TVA au Brésil, les documents fiscaux électroniques (NF-e, NFC-e, NFS-e) doivent désormais inclure les nouveaux champs CBS et IBS à des taux de test de 0,9 % et 0,1 % respectivement. Il n''y a pas encore d''impact financier à ces taux de test, mais l''obligation légale d''inclure correctement les données s''applique déjà — et la validation se durcit considérablement à partir d''avril.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.nfe.fazenda.gov.br/portal/principal.aspx" target="_blank" rel="noopener">🔗 Source officielle : Portal Nacional da NF-e (SEFAZ)</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-croatia-fiskalizacija-2', 'fr', 'Croatie — Fiskalizacija 2.0 entre en vigueur', 'Fiskalizacija 2.0 en Croatie impose la facturation électronique B2B structurée et le télédéclaration en temps réel pour tous les assujettis à la TVA.', '<h3>🇭🇷 Croatie — Fiskalizacija 2.0 entre en vigueur</h3><p>La plus grande réforme de facturation électronique jamais menée en Croatie : l''émission structurée, la réception et le télédéclaration en temps réel sont désormais obligatoires pour tous les contribuables assujettis à la TVA établis en Croatie — s''ajoutant à l''obligation B2G déjà en vigueur depuis 2019. Cela inclut un flux de fiscalisation de 5 jours côté acheteur et un télédéclaration mensuel avant le 20 de chaque mois, ainsi qu''une obligation d''archivage de 11 ans pour les factures XML originales.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://porezna-uprava.gov.hr/en" target="_blank" rel="noopener">🔗 Source officielle : Porezna uprava (Administration fiscale croate)</a></p><p><strong>Ce que cela signifie pour votre équipe :</strong> si vous opérez sur l''un de ces six marchés, c''est le moment de confirmer — et non de supposer — que ce qui a été mis en place pendant les fêtes fonctionne réellement correctement en production, et pas seulement configuré et laissé sans test.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-malaysia-myinvois-phase-4', 'fr', 'Malaisie — la Phase 4 de MyInvois commence', 'La Phase 4 de MyInvois fait entrer les entreprises dont le chiffre d''affaires est compris entre 1 et 5 millions de RM dans l''obligation de facturation électronique de Malaisie.', '<h3>🇲🇾 Malaisie — la Phase 4 de MyInvois commence</h3><p>Les entreprises dont le chiffre d''affaires annuel se situe entre 1 million et 5 millions de RM entrent aujourd''hui dans l''obligation, avec une période d''assouplissement des sanctions pour erreurs de soumission courant jusqu''à fin 2027. Les factures électroniques individuelles supérieures à 10 000 RM sont désormais obligatoires — la facturation consolidée n''est plus autorisée pour des montants de ce niveau.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Source officielle : LHDN — MyInvois / e-Invoice</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-mexico-2026-tax-reform', 'fr', 'Mexique — la réforme fiscale 2026 entre en vigueur', 'La réforme fiscale 2026 du Mexique renforce les pouvoirs de contrôle du SAT, introduisant une responsabilité pénale pour les CFDI falsifiés.', '<h3>🇲🇽 Mexique — la réforme fiscale 2026 entre en vigueur</h3><p>Les pouvoirs de contrôle du SAT se renforcent à compter d''aujourd''hui, avec des vérifications d''authenticité plus strictes et — fait notable — une nouvelle responsabilité pénale pour les CFDI falsifiés ou simulés. Il s''agit d''une escalade significative par rapport au cadre de sanctions purement administratif précédent. Il est utile de revoir dès maintenant votre documentation de défense et vos procédures d''annulation, étant donné que le SAT peut exiger des pièces justificatives sous seulement 5 jours ouvrés.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.sat.gob.mx" target="_blank" rel="noopener">🔗 Source officielle : SAT — Servicio de Administración Tributaria</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-new-zealand-agency-einvoicing', 'fr', 'Nouvelle-Zélande — les organismes publics à fort volume doivent envoyer et recevoir des factures électroniques', 'Les organismes publics néo-zélandais à fort volume doivent désormais envoyer et recevoir des factures électroniques au format PINT A-NZ.', '<h3>🇳🇿 Nouvelle-Zélande — les organismes publics à fort volume doivent envoyer et recevoir des factures électroniques</h3><p>Les organismes traitant plus de 2 000 factures commerciales nationales par an doivent désormais être pleinement capables d''envoyer et de recevoir des factures électroniques structurées — au format PINT A-NZ, obligatoire pour la facturation électronique publique depuis mai 2025 — et doivent en payer 95 % sous 5 jours ouvrés. Si vous fournissez un organisme à ce volume, c''est le moment où les délais de paiement devraient réellement commencer à s''améliorer.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.einvoicing.govt.nz" target="_blank" rel="noopener">🔗 Source officielle : einvoicing.govt.nz — MBIE</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-01-belgium-croatia-january-check-in', 'fr', 'Point sur le mois de janvier', 'Un point de suivi sur les obligations de janvier en Belgique et en Croatie, avec un rappel de tester les intégrations de bout en bout, pas seulement de confirmer la connectivité.', '<h3>Point sur le mois de janvier</h3><p>Un bref suivi sur le groupe de six pays du mois dernier : si vous opérez en Belgique ou en Croatie et que vous n''avez pas encore testé votre intégration de bout en bout — pas seulement confirmé qu''elle est techniquement connectée —, c''est un bon mois pour le faire. Les deux obligations comportent de véritables sanctions pour des lacunes qui n''apparaissent qu''une fois qu''un volume réel de factures commence à circuler, plutôt que dans un test en environnement isolé.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-01-poland-ksef-large-taxpayers', 'fr', 'Pologne — KSeF obligatoire pour les grands contribuables', 'La plateforme de contrôle KSeF de la Pologne devient obligatoire pour les grands contribuables dont le chiffre d''affaires dépasse 200 millions de PLN.', '<h3>🇵🇱 Pologne — KSeF obligatoire pour les grands contribuables</h3><p>Les grands contribuables dont le chiffre d''affaires dépasse 200 millions de PLN sont devenus aujourd''hui le premier groupe tenu d''émettre des factures B2B via la plateforme de contrôle Krajowy System e-Faktur (KSeF). Il s''agit d''un véritable modèle de contrôle — une facture n''a aucun effet légal tant que KSeF ne l''a pas validée et contrôlée, via le schéma XML FA(3) soumis par API. Tous les autres suivent en avril, et les micro-entrepreneurs à partir de janvier 2027 ; la Pologne échelonne délibérément cette mise en œuvre selon la taille du contribuable plutôt que de tout activer d''un coup, ce qui vaut la peine d''être su si vous êtes une petite entreprise supposant être déjà concernée.</p><p><strong>Ce que cela signifie pour votre équipe :</strong> si vous êtes un grand contribuable polonais, ce n''est plus un exercice de planification. Confirmez que votre intégration API avec KSeF est réellement active, et que le personnel ainsi que toute autorisation d''émetteur tiers sont correctement configurés — une autorisation mal configurée est l''une des causes les plus courantes d''échec silencieux du contrôle dans les premières semaines.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ksef.mf.gov.pl/" target="_blank" rel="noopener">🔗 Source officielle : KSeF — Ministère des Finances</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-01-chile-digital-boleta-delivery', 'fr', 'Chili — livraison numérique requise sans imprimante', 'Le Chili exige désormais la livraison numérique de la boleta electrónica pour les commerces sans capacité d''impression au point de vente.', '<h3>🇨🇱 Chili — livraison numérique requise sans imprimante</h3><p>Les commerces sans capacité d''impression au point de vente doivent désormais livrer la <em>boleta electrónica</em> de manière numérique — par e-mail, SMS, WhatsApp, code QR ou un canal électronique équivalent — plutôt que de simplement omettre la livraison. Une règle mineure, mais qui comble une réelle lacune pour les vendeurs mobiles, les pop-up stores et les activités de livraison uniquement, qui n''avaient auparavant aucune voie clairement conforme en l''absence d''imprimante physique.</p><p><strong>Ce que cela signifie pour votre équipe :</strong> si vous exploitez un point de vente sans imprimante physique — marchés, pop-up stores, dispositifs de livraison uniquement —, confirmez que l''un de ces canaux électroniques fonctionne réellement dès aujourd''hui, pas seulement prévu pour plus tard. Les commerces disposant d''imprimantes doivent généralement continuer à livrer la représentation imprimée comme auparavant.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.sii.cl" target="_blank" rel="noopener">🔗 Source officielle : Servicio de Impuestos Internos (SII)</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-01-saudi-arabia-zatca-wave-23', 'fr', 'Arabie saoudite — ZATCA Fatoora Vague 23', 'La Vague 23 de ZATCA fait entrer les entreprises dont le chiffre d''affaires dépasse 750 000 SAR dans les exigences de contrôle en temps réel de Fatoora.', '<h3>🇸🇦 Arabie saoudite — ZATCA Fatoora Vague 23</h3><p>Les entreprises dont le chiffre d''affaires soumis à la TVA dépassait 750 000 SAR en 2022, 2023 ou 2024 devaient achever aujourd''hui l''intégration de la Phase 2 avec la plateforme Fatoora pour le contrôle en temps réel — ce qui signifie que les factures portent un UUID, un code QR et un cachet cryptographique, soumis via API pour un contrôle B2B/B2G en temps réel. ZATCA poursuit son déploiement par vagues — la Vague 24 suivra en juin, abaissant le seuil à 375 000 SAR et faisant entrer la quasi-totalité des entreprises assujetties à la TVA du pays.</p><p><strong>Ce que cela signifie pour votre équipe :</strong> si votre chiffre d''affaires a dépassé 750 000 SAR lors de l''une de ces trois années de référence, supposez que vous êtes dans la Vague 23 sauf indication contraire de ZATCA — la notification directe arrive généralement environ six mois à l''avance, donc si vous n''avez rien reçu alors que vous pensez le devoir, il vaut mieux vérifier proactivement plutôt que d''attendre une lettre qui pourrait déjà être en retard.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://zatca.gov.sa" target="_blank" rel="noopener">🔗 Source officielle : ZATCA — Fatoora</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-01-brazil-cbs-ibs-validation', 'fr', 'Brésil — la validation CBS/IBS commence', 'Le Brésil commence à valider rigoureusement les champs fiscaux CBS/IBS, risquant le rejet automatique des factures aux données manquantes ou incohérentes.', '<h3>🇧🇷 Brésil — la validation CBS/IBS commence</h3><p>Alors que la réforme de la double TVA au Brésil progresse, les systèmes d''autorisation ont commencé aujourd''hui à valider rigoureusement les nouveaux champs fiscaux CBS et IBS sur les documents NF-e, NFC-e et NFS-e. Les factures aux données manquantes ou incohérentes risquent désormais un rejet automatique — encore à des taux de test (0,9 % / 0,1 %), donc sans impact financier pour l''instant, mais une facture rejetée peut tout de même bloquer le mouvement des marchandises, indépendamment du caractère nominal du taux.</p><p><strong>Ce que cela signifie pour votre équipe :</strong> si ce n''est pas déjà fait, auditez dès maintenant votre production de factures pour vérifier la complétude des groupes de données CBS/IBS/IS, tant que les enjeux restent faibles — attendre que les taux entrent pleinement en vigueur en août, selon la Note technique 2025.002-RTC, laisse peu de marge.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.nfe.fazenda.gov.br/portal/principal.aspx" target="_blank" rel="noopener">🔗 Source officielle : Portal Nacional da NF-e (SEFAZ)</a></p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">Le détail technique complet de ces deux sujets se trouve dans leurs analyses par pays respectives — Pologne et Brésil — si vous avez besoin du tableau complet pour un briefing.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-04-01-poland-ksef-universal', 'fr', 'Pologne — l''obligation KSeF devient universelle', 'L''obligation KSeF de la Pologne devient universelle pour les entreprises assujetties à la TVA, mettant fin totalement à l''ancien processus de note de correction.', '<h3>🇵🇱 Pologne — l''obligation KSeF devient universelle</h3><p>À compter d''aujourd''hui, l''exigence KSeF de la Pologne s''étend à pratiquement toutes les entreprises restantes assujetties à la TVA (les micro-entrepreneurs restent sur une trajectoire distincte, les rejoignant à partir de janvier 2027). À partir de cette date, une facture n''a force légale qu''une fois contrôlée par KSeF — et les anciennes notes de correction (<em>noty korygujące</em>) ne sont plus du tout valables ; les corrections doivent désormais passer par le propre processus de correction structuré de KSeF.</p><p><strong>Ce que cela signifie pour votre équipe :</strong> si vous avez un flux de facturation B2B polonais qui était auparavant exempté, confirmez que votre système génère désormais réellement des factures structurées FA(3) valides, et ne se contente pas de le prévoir d''ici la fin de l''année. Également à vérifier : à partir du 1er août 2026, les numéros de facture KSeF doivent aussi figurer sur les références de virement bancaire — un détail mineur qu''une équipe de trésorerie peut facilement manquer si elle n''a pas été associée au déploiement de la facturation électronique.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://ksef.mf.gov.pl/" target="_blank" rel="noopener">🔗 Source officielle : KSeF — Ministère des Finances</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-01-2027-wave-multi-country-outlook', 'fr', 'Perspectives : la vague de 2027 se précise', 'Un aperçu de la vague de janvier 2027, alors que les contribuables restants de Pologne, le déploiement de VeriFactu en Espagne et l''obligation de Phase 1 des EAU convergent tous vers la même fenêtre de mise en service.', '<h3>Perspectives : la vague de 2027 se précise</h3><p>La Slovaquie n''est pas seule — les micro-entrepreneurs restants de Pologne, le déploiement de VeriFactu en Espagne et l''obligation de Phase 1 des EAU visent également tous une mise en service en janvier 2027. Si votre entreprise touche plusieurs de ces marchés, c''est un moment raisonnable pour lancer une évaluation de préparation commune à tous, plutôt que de traiter chacun comme un exercice d''urgence séparé plus tard dans l''année.</p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">Si vous ne l''avez pas encore vu, « Se préparer à une obligation », sous le menu Ressources, traite exactement de ce type de planification multi-pays.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-01-slovakia-voluntary-testing', 'fr', 'Slovaquie — début de la période de transition volontaire', 'La Slovaquie ouvre les tests volontaires de son réseau distinctif Digital Postman à 5 coins avant son obligation de janvier 2027.', '<h3>🇸🇰 Slovaquie — début de la période de transition volontaire</h3><p>Les entreprises peuvent désormais s''inscrire pour tester volontairement la facturation électronique structurée et le télédéclaration avant l''obligation de janvier 2027 de la Slovaquie, en utilisant le modèle décentralisé distinctif « à 5 coins » du pays, construit sur des points d''accès certifiés <em>Digital Postman</em> fonctionnant sur Peppol — une variante que nous ne voyons répliquée exactement nulle part ailleurs parmi ce que nous suivons.</p><p><strong>Ce que cela signifie pour votre équipe :</strong> si vous commercez avec des assujettis à la TVA slovaques, cela vaut vraiment la peine de le faire tôt plutôt que d''attendre. À partir de 2027, les déductions de TVA en amont ne pourront plus être réclamées sur des factures entrantes non conformes — une véritable conséquence de trésorerie, pas seulement administrative. Tester maintenant, alors qu''il n''y a aucune sanction en cas d''erreur, est le moyen économique de détecter les problèmes d''intégration avant qu''ils ne vous coûtent de l''argent.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.financnasprava.sk/en/homepage" target="_blank" rel="noopener">🔗 Source officielle : Administration financière de la République slovaque</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-australia-peppol-threshold-preview', 'fr', 'Australie — seuil Peppol de 30 % pour les factures fédérales', 'Le seuil Peppol de 30 % de l''Australie pour les factures fédérales entre en vigueur le 1er juillet — un aperçu de ce qui arrive et de ce qu''il faut vérifier avant.', '<h3>🇦🇺 Australie — seuil Peppol de 30 % pour les factures fédérales</h3><p>À partir du 1er juillet, les entités non constituées en société du Commonwealth doivent faire transiter au moins 30 % des factures fournisseurs reçues par le réseau Peppol, en vue d''une automatisation complète d''ici décembre, avec un rapport d''avancement trimestriel à l''Autorité Peppol australienne. Si vous fournissez des agences fédérales australiennes, c''est un bon moment pour confirmer que votre facturation est réellement compatible Peppol en utilisant le format PINT A-NZ — le seul standard pris en charge depuis mai 2025 — et pas seulement techniquement capable de l''être.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing" target="_blank" rel="noopener">🔗 Source officielle : ATO — About eInvoicing</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-denmark-small-business-bookkeeping-preview', 'fr', 'Danemark — les petites entreprises sur systèmes personnalisés rejoignent l''obligation', 'Les exigences numériques de la loi danoise sur la comptabilité s''étendent aux petites entreprises sur systèmes personnalisés à partir du 1er juillet — il vaut la peine de vérifier dès maintenant votre chiffre d''affaires par rapport au seuil.', '<h3>🇩🇰 Danemark — les petites entreprises sur systèmes personnalisés rejoignent l''obligation</h3><p>Les petites entreprises et entreprises individuelles dépassant 300 000 DKK de chiffre d''affaires sur deux années consécutives, utilisant des systèmes comptables non enregistrés (« personnalisés »), deviennent pleinement soumises aux exigences numériques de la loi sur la comptabilité. Il vaut la peine de vérifier si votre chiffre d''affaires a réellement dépassé ce seuil au cours des deux derniers exercices — il est facile de supposer être encore en dessous sans réellement vérifier les chiffres.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://erhvervsstyrelsen.dk" target="_blank" rel="noopener">🔗 Source officielle : Erhvervsstyrelsen (Autorité danoise des entreprises)</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-malaysia-related-company-rule-preview', 'fr', 'Malaisie — les entreprises liées à des groupes de 1 million de RM+ désormais concernées', 'La règle des entreprises liées de MyInvois en Malaisie entre en vigueur le 1er juillet, touchant les filiales de groupes de 1 million de RM ou plus, indépendamment de leur propre chiffre d''affaires.', '<h3>🇲🇾 Malaisie — les entreprises liées à des groupes de 1 million de RM+ désormais concernées</h3><p>Voici celle qui a le plus de chances de prendre une entreprise au dépourvu : même si votre propre chiffre d''affaires est bien inférieur aux seuils de la Malaisie, si vous êtes une filiale ou une entreprise liée à un groupe dont le chiffre d''affaires atteint ou dépasse 1 million de RM, vous êtes concerné à partir du 1er juillet, quelle que soit votre propre taille individuelle. C''est la structure du groupe, et non le chiffre d''affaires individuel, qui détermine si vous êtes visé ici.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Source officielle : LHDN — MyInvois / e-Invoice</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-uae-voluntary-pilot-preview', 'fr', 'EAU — ouverture du pilote volontaire de facturation électronique', 'Les EAU ouvrent un pilote volontaire de facturation électronique à partir du 1er juillet, permettant aux entreprises de tester la connectivité ASP avant les phases obligatoires de janvier 2027.', '<h3>🇦🇪 EAU — ouverture du pilote volontaire de facturation électronique</h3><p>Avant les phases obligatoires débutant en janvier 2027, les EAU ouvrent la participation volontaire à cette date — permettant aux entreprises de tester la connectivité avec un Prestataire de Services Agréé et le format PINT AE sans risque avant que les sanctions ne s''appliquent. Étant donné que la date limite de désignation de l''ASP pour les grandes entreprises tombe en octobre, utiliser judicieusement cette fenêtre pilote bien avant cette échéance est véritablement l''ordre logique des choses.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://mof.gov.ae/en/about-ministry/mof-initiatives/einvoicing/" target="_blank" rel="noopener">🔗 Source officielle : Ministère des Finances des EAU — eInvoicing</a></p><p><strong>Ce que cela signifie pour votre équipe :</strong> si l''un de ces quatre cas vous concerne, c''est le mois pour véritablement terminer les tests, pas pour les commencer. Le 1er juillet arrive vite, et aucun de ces quatre cas ne laisse beaucoup de délai de grâce une fois la date passée.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-australia-peppol-threshold-live', 'fr', 'Australie — le seuil Peppol de 30 % est désormais en vigueur', 'Le seuil Peppol de 30 % de l''Australie pour les factures fédérales est désormais en vigueur, avec un rapport d''avancement trimestriel à l''Autorité Peppol australienne.', '<h3>🇦🇺 Australie — le seuil Peppol de 30 % est désormais en vigueur</h3><p>Les agences fédérales doivent désormais faire transiter au moins 30 % des factures fournisseurs reçues par Peppol, avec un rapport d''avancement trimestriel à l''Autorité Peppol australienne. Si vous fournissez ce secteur et n''avez pas confirmé que votre facturation est compatible Peppol, ce n''est plus une tâche « à faire bientôt » — c''est une lacune de conformité active.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing" target="_blank" rel="noopener">🔗 Source officielle : ATO — About eInvoicing</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-denmark-small-business-bookkeeping-live', 'fr', 'Danemark — les petites entreprises sur systèmes personnalisés désormais concernées', 'Les exigences numériques de la loi danoise sur la comptabilité s''appliquent désormais activement aux petites entreprises sur systèmes personnalisés au-delà du seuil de 300 000 DKK.', '<h3>🇩🇰 Danemark — les petites entreprises sur systèmes personnalisés désormais concernées</h3><p>Les exigences numériques de la loi sur la comptabilité s''appliquent désormais aux petites entreprises et entreprises individuelles dépassant le seuil biennal de 300 000 DKK utilisant des systèmes non enregistrés, y compris l''obligation de conserver des enregistrements numériques pendant 5 ans avec sauvegarde externe automatisée.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://erhvervsstyrelsen.dk" target="_blank" rel="noopener">🔗 Source officielle : Erhvervsstyrelsen (Autorité danoise des entreprises)</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-malaysia-related-company-rule-live', 'fr', 'Malaisie — la règle des entreprises liées désormais active', 'La règle des entreprises liées de MyInvois en Malaisie est désormais active, faisant entrer dans le champ d''application les filiales de groupes de 1 million de RM ou plus.', '<h3>🇲🇾 Malaisie — la règle des entreprises liées désormais active</h3><p>Les filiales et entreprises liées à des groupes de 1 million de RM ou plus sont désormais dans le champ d''application de MyInvois, indépendamment de leur propre chiffre d''affaires individuel. Il vaut la peine de faire aujourd''hui une dernière vérification de la structure de votre groupe si vous n''avez pas encore confirmé votre statut.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://www.hasil.gov.my/en/e-invoice" target="_blank" rel="noopener">🔗 Source officielle : LHDN — MyInvois / e-Invoice</a></p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-poland-bank-transfer-reference-preview', 'fr', 'Ce que nous surveillons pour août', 'Un aperçu de l''exigence polonaise, à partir du 1er août, d''inclure les numéros de facture KSeF sur les références de virement bancaire — un détail facile à manquer pour les équipes de trésorerie.', '<h3>Ce que nous surveillons pour août</h3><p>L''exigence polonaise d''inclure le numéro de facture KSeF sur les virements bancaires entre en vigueur le 1er août — un détail mineur mais facile à manquer si votre équipe de trésorerie/paiements n''est pas déjà associée à votre déploiement de facturation électronique. Nous le traiterons en détail dans le prochain numéro, avec le lien KSeF officiel comme toujours.</p><p style="color:#7a6f52; font-size:12.5px; margin-top:20px;">Comme toujours, les analyses par pays contiennent le détail technique complet derrière chacun de ces sujets si vous devez informer votre équipe au-delà de ce résumé.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-uae-voluntary-pilot-live', 'fr', 'EAU — le pilote volontaire est désormais ouvert', 'Le pilote volontaire de facturation électronique des EAU est désormais ouvert, avant les phases obligatoires de janvier 2027 et la date limite d''octobre pour la désignation de l''ASP par les grandes entreprises.', '<h3>🇦🇪 EAU — le pilote volontaire est désormais ouvert</h3><p>Les entreprises peuvent désormais tester la connectivité avec un Prestataire de Services Agréé et le format PINT AE avant les phases obligatoires de janvier 2027 — cela vaut vraiment la peine de commencer immédiatement, étant donné que la date limite de désignation de l''ASP pour les grandes entreprises tombe en octobre.</p><p style="margin:4px 0 16px 0; font-size:12.8px;"><a style="color:#b5432f; text-decoration:underline; font-weight:600;" href="https://mof.gov.ae/en/about-ministry/mof-initiatives/einvoicing/" target="_blank" rel="noopener">🔗 Source officielle : Ministère des Finances des EAU — eInvoicing</a></p>');
